// Builds src/css/tokens.css and the docs specimen classes from the W3C design token files (DTCG 2025.10) here.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const ROOT_PX = 16;

const HEADER =
  "/* Generated by design-system/tokens/build.mjs from its *.tokens.json files. Do not edit. */";

export const TOKEN_FILES = [
  "primitives",
  "semantic",
  "dimensions",
  "typography",
  "effects",
];

export class TokenSet {
  tokens = new Map();

  constructor(trees) {
    for (const tree of trees) this.#collect(tree, [], undefined);
  }

  static load(dir) {
    return new TokenSet(
      TOKEN_FILES.map((name) =>
        JSON.parse(readFileSync(new URL(`${name}.tokens.json`, dir), "utf8")),
      ),
    );
  }

  static kebabName(path) {
    return path.replaceAll(".", "-");
  }

  static cssName(path) {
    return `--${TokenSet.kebabName(path)}`;
  }

  css() {
    const lines = this.declarations().map(
      ([name, value]) => `  ${name}: ${value};`,
    );
    const typeClasses = this.#paths("typography").map((path) => {
      const name = TokenSet.kebabName(path);
      return `.${name} {\n  font: var(--${name});\n  letter-spacing: var(--${name}-letter-spacing);\n}`;
    });
    return `${HEADER}\n:root {\n${lines.join("\n")}\n}\n\n${typeClasses.join("\n\n")}\n`;
  }

  // Docs only: one class per token that exposes it as --token, so specimens need no inline styles.
  specimenCss() {
    const rules = this.#paths("color", "dimension", "shadow").map((path) => {
      const name = TokenSet.kebabName(path);
      return `.token-${name} {\n  --token: var(--${name});\n}`;
    });
    return `${HEADER}\n${rules.join("\n\n")}\n`;
  }

  #paths(...types) {
    return [...this.tokens]
      .filter(([, token]) => types.includes(token.$type))
      .map(([path]) => path);
  }

  declarations() {
    return [...this.tokens].flatMap(([path, token]) =>
      this.#declare(TokenSet.cssName(path), token, path),
    );
  }

  #collect(group, path, inheritedType) {
    const type = group.$type ?? inheritedType;
    for (const [key, node] of Object.entries(group)) {
      if (key.startsWith("$")) continue;
      const nodePath = [...path, key];
      if (!("$value" in node)) {
        this.#collect(node, nodePath, type);
        continue;
      }
      const name = nodePath.join(".");
      if (this.tokens.has(name)) throw new Error(`Duplicate token ${name}`);
      this.tokens.set(name, { ...node, $type: node.$type ?? type });
    }
  }

  #declare(name, { $type, $value }, path) {
    switch ($type) {
      case "color":
        return [[name, this.#color($value)]];
      case "dimension":
        return [
          [
            name,
            path.startsWith("border-width.")
              ? this.#dimension($value)
              : this.#rem($value),
          ],
        ];
      case "fontFamily":
        return [[name, this.#fontFamily($value)]];
      case "typography":
        return [
          [name, this.#font($value)],
          [
            `${name}-letter-spacing`,
            this.#em($value.letterSpacing, $value.fontSize),
          ],
        ];
      case "shadow":
        return [[name, $value.map((layer) => this.#shadow(layer)).join(", ")]];
      default:
        throw new Error(`Unsupported $type ${$type} at ${path}`);
    }
  }

  #reference(value) {
    const path = /^\{(.+)\}$/.exec(value)?.[1];
    if (!path || !this.tokens.has(path))
      throw new Error(`Unknown reference ${value}`);
    return `var(${TokenSet.cssName(path)})`;
  }

  #color(value) {
    if (typeof value === "string") return this.#reference(value);
    if (value.alpha === undefined) return value.hex;
    return (
      value.hex +
      Math.round(value.alpha * 255)
        .toString(16)
        .padStart(2, "0")
    );
  }

  #dimension(value) {
    if (typeof value === "string") return this.#reference(value);
    return value.value === 0 ? "0" : `${value.value}${value.unit}`;
  }

  // Sizes follow the reader's font-size setting; borders and shadows stay in px.
  #rem(value) {
    if (typeof value === "string" || value.unit !== "px" || value.value === 0)
      return this.#dimension(value);
    return `${+(value.value / ROOT_PX).toFixed(4)}rem`;
  }

  #em(value, fontSize) {
    if (value.value === 0) return "0";
    return `${+(value.value / fontSize.value).toFixed(4)}em`;
  }

  #fontFamily(value) {
    if (typeof value === "string") return this.#reference(value);
    return value
      .map((name) => (name.includes(" ") ? `"${name}"` : name))
      .join(", ");
  }

  #font({ fontWeight, fontSize, lineHeight, fontFamily }) {
    return `${fontWeight} ${this.#rem(fontSize)}/${lineHeight} ${this.#fontFamily(fontFamily)}`;
  }

  #shadow({ offsetX, offsetY, blur, spread, color }) {
    const lengths = [offsetX, offsetY, blur, spread].map((d) =>
      this.#dimension(d),
    );
    return `${lengths.join(" ")} ${this.#color(color)}`;
  }
}

export const OUTPUT = new URL("../../src/css/tokens.css", import.meta.url);
export const SPECIMENS = new URL(
  "../docs/src/styles/specimens.css",
  import.meta.url,
);

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const set = TokenSet.load(new URL("./", import.meta.url));
  writeFileSync(OUTPUT, set.css());
  writeFileSync(SPECIMENS, set.specimenCss());
  console.log(
    `Wrote ${set.tokens.size} tokens to src/css/tokens.css and the docs specimens`,
  );
}
